BEGIN;

-- =========================================================
-- ROLES
-- =========================================================

CREATE TABLE IF NOT EXISTS roles (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" varchar(100) NOT NULL,
    "Descripcion" varchar(250),
    "Activo" boolean NOT NULL DEFAULT TRUE,
    "FechaCreacion" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "PK_roles"
        PRIMARY KEY ("Id"),

    CONSTRAINT "UQ_roles_nombre"
        UNIQUE ("Nombre")
);


-- =========================================================
-- PERMISOS
-- =========================================================

CREATE TABLE IF NOT EXISTS permisos (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" varchar(150) NOT NULL,
    "Modulo" varchar(100) NOT NULL,
    "Descripcion" varchar(250),
    "Activo" boolean NOT NULL DEFAULT TRUE,

    CONSTRAINT "PK_permisos"
        PRIMARY KEY ("Id"),

    CONSTRAINT "UQ_permisos_nombre"
        UNIQUE ("Nombre")
);


-- =========================================================
-- USUARIO - ROL
-- =========================================================

CREATE TABLE IF NOT EXISTS usuario_roles (
    "UsuarioId" integer NOT NULL,
    "RolId" integer NOT NULL,
    "FechaAsignacion" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "PK_usuario_roles"
        PRIMARY KEY ("UsuarioId", "RolId"),

    CONSTRAINT "FK_usuario_roles_usuario"
        FOREIGN KEY ("UsuarioId")
        REFERENCES usuarios("Id")
        ON DELETE RESTRICT,

    CONSTRAINT "FK_usuario_roles_rol"
        FOREIGN KEY ("RolId")
        REFERENCES roles("Id")
        ON DELETE RESTRICT
);


-- =========================================================
-- ROL - PERMISO
-- =========================================================

CREATE TABLE IF NOT EXISTS rol_permisos (
    "RolId" integer NOT NULL,
    "PermisoId" integer NOT NULL,

    CONSTRAINT "PK_rol_permisos"
        PRIMARY KEY ("RolId", "PermisoId"),

    CONSTRAINT "FK_rol_permisos_rol"
        FOREIGN KEY ("RolId")
        REFERENCES roles("Id")
        ON DELETE RESTRICT,

    CONSTRAINT "FK_rol_permisos_permiso"
        FOREIGN KEY ("PermisoId")
        REFERENCES permisos("Id")
        ON DELETE RESTRICT
);


-- =========================================================
-- ROLES INICIALES
-- =========================================================

INSERT INTO roles
(
    "Nombre",
    "Descripcion"
)
VALUES
(
    'Administrador',
    'Acceso completo a la plataforma.'
),
(
    'Gestor de Actas',
    'Gestiona equipos, actas y procesos relacionados.'
),
(
    'Mensajero',
    'Encargado de la entrega física y recolección de firma en campo.'
),
(
    'Consulta',
    'Permite consultar información autorizada.'
)
ON CONFLICT ("Nombre")
DO NOTHING;


-- =========================================================
-- PERMISOS
-- =========================================================

INSERT INTO permisos
(
    "Nombre",
    "Modulo",
    "Descripcion"
)
VALUES

-- =========================================================
-- USUARIOS
-- =========================================================

(
    'USUARIOS_CONSULTAR',
    'Usuarios',
    'Permite consultar la información de los usuarios registrados.'
),

(
    'USUARIOS_REGISTRAR',
    'Usuarios',
    'Permite registrar nuevos usuarios en la plataforma.'
),

(
    'USUARIOS_EDITAR',
    'Usuarios',
    'Permite modificar la información de los usuarios.'
),

(
    'USUARIOS_DESACTIVAR',
    'Usuarios',
    'Permite activar o desactivar usuarios.'
),


-- =========================================================
-- EQUIPOS
-- =========================================================

(
    'EQUIPOS_CONSULTAR',
    'Equipos',
    'Permite consultar el inventario de equipos.'
),

(
    'EQUIPOS_REGISTRAR',
    'Equipos',
    'Permite registrar nuevos equipos en el inventario.'
),

(
    'EQUIPOS_EDITAR',
    'Equipos',
    'Permite modificar la información de los equipos.'
),

(
    'EQUIPOS_DESACTIVAR',
    'Equipos',
    'Permite retirar o desactivar equipos del inventario.'
),


-- =========================================================
-- ACTAS
-- =========================================================

(
    'ACTAS_CONSULTAR',
    'Actas',
    'Permite consultar las actas registradas.'
),

(
    'ACTAS_REGISTRAR',
    'Actas',
    'Permite registrar nuevas actas.'
),

(
    'ACTAS_EDITAR',
    'Actas',
    'Permite modificar las actas registradas.'
),

(
    'ACTAS_FIRMAR',
    'Actas',
    'Permite realizar la firma de las actas.'
),

(
    'ACTAS_EXPORTAR',
    'Actas',
    'Permite exportar las actas registradas.'
),


-- =========================================================
-- MENSAJERO
-- =========================================================

(
    'MENSAJERO_ACTAS_CONSULTAR',
    'Mensajero',
    'Permite consultar las actas asignadas al mensajero.'
),

(
    'MENSAJERO_ACTAS_FIRMAR',
    'Mensajero',
    'Permite al mensajero registrar la firma manuscrita en entrega.'
),

(
    'MENSAJERO_ACTAS_ENTREGAR',
    'Mensajero',
    'Permite confirmar la entrega física del equipo.'
),

(
    'MENSAJERO_ACTAS_DEVOLVER',
    'Mensajero',
    'Permite gestionar la devolución física del equipo.'
),


-- =========================================================
-- REPORTES
-- =========================================================

(
    'REPORTES_CONSULTAR',
    'Reportes',
    'Permite consultar los reportes disponibles.'
),

(
    'REPORTES_EXPORTAR',
    'Reportes',
    'Permite exportar los reportes generados.'
),


-- =========================================================
-- ROLES
-- =========================================================

(
    'ROLES_CONSULTAR',
    'Roles',
    'Permite consultar los roles y permisos configurados.'
),

(
    'ROLES_CREAR',
    'Roles',
    'Permite crear nuevos roles.'
),

(
    'ROLES_EDITAR',
    'Roles',
    'Permite modificar los roles existentes.'
),

(
    'ROLES_ELIMINAR',
    'Roles',
    'Permite eliminar roles.'
)

ON CONFLICT ("Nombre")
DO NOTHING;


-- =========================================================
-- ADMINISTRADOR
-- TODOS LOS PERMISOS
-- =========================================================

INSERT INTO rol_permisos
(
    "RolId",
    "PermisoId"
)
SELECT
    r."Id",
    p."Id"
FROM roles r
CROSS JOIN permisos p
WHERE r."Nombre" = 'Administrador'
ON CONFLICT
(
    "RolId",
    "PermisoId"
)
DO NOTHING;


-- =========================================================
-- GESTOR DE ACTAS
-- =========================================================

INSERT INTO rol_permisos
(
    "RolId",
    "PermisoId"
)
SELECT
    r."Id",
    p."Id"
FROM roles r
INNER JOIN permisos p
    ON p."Nombre" IN
    (
        'EQUIPOS_CONSULTAR',
        'EQUIPOS_REGISTRAR',
        'EQUIPOS_EDITAR',
        'ACTAS_CONSULTAR',
        'ACTAS_REGISTRAR',
        'ACTAS_EDITAR',
        'ACTAS_FIRMAR',
        'ACTAS_EXPORTAR',
        'REPORTES_CONSULTAR',
        'REPORTES_EXPORTAR'
    )
WHERE r."Nombre" = 'Gestor de Actas'
ON CONFLICT
(
    "RolId",
    "PermisoId"
)
DO NOTHING;


-- =========================================================
-- MENSAJERO
-- =========================================================

INSERT INTO rol_permisos
(
    "RolId",
    "PermisoId"
)
SELECT
    r."Id",
    p."Id"
FROM roles r
INNER JOIN permisos p
    ON p."Nombre" IN
    (
        'MENSAJERO_ACTAS_CONSULTAR',
        'MENSAJERO_ACTAS_FIRMAR',
        'MENSAJERO_ACTAS_ENTREGAR',
        'MENSAJERO_ACTAS_DEVOLVER'
    )
WHERE r."Nombre" = 'Mensajero'
ON CONFLICT
(
    "RolId",
    "PermisoId"
)
DO NOTHING;


-- =========================================================
-- CONSULTA
-- =========================================================

INSERT INTO rol_permisos
(
    "RolId",
    "PermisoId"
)
SELECT
    r."Id",
    p."Id"
FROM roles r
INNER JOIN permisos p
    ON p."Nombre" IN
    (
        'EQUIPOS_CONSULTAR',
        'ACTAS_CONSULTAR',
        'REPORTES_CONSULTAR'
    )
WHERE r."Nombre" = 'Consulta'
ON CONFLICT
(
    "RolId",
    "PermisoId"
)
DO NOTHING;


COMMIT;